package com.beatoflove.standardcalculator;
import java.util.*;
public final class FormulaProTest {
    static int count;
    static void eq(double a,double b){if(!Double.isFinite(a)||Math.abs(a-b)>1e-8*Math.max(1,Math.abs(b)))throw new AssertionError(a+" != "+b);count++;}
    static void ok(boolean b){if(!b)throw new AssertionError();count++;}
    static void bad(Runnable r){boolean fail=false;try{r.run();}catch(IllegalArgumentException x){fail=true;}ok(fail);}
    public static void main(String[] args){FormulaEngine e=new FormulaEngine();
        String[] xs={"2+3*4","(2+3)*4","-2^2","2^-3","2^3^2","2pi","2(3+4)","1/3+1/6","mixed(2,1,3)","sqrt(81)","cbrt(-27)","root(3,-8)","sin(30)","cos(60)","tan(45)","asin(.5)","acos(.5)","atan(1)","sinh(0)","cosh(0)","tanh(0)","asinh(0)","acosh(1)","atanh(0)","log(100)","ln(e)","exp(1)","pow10(3)","logbase(2,8)","fact(5)","5!","ncr(5,2)","npr(5,2)","inv(4)","abs(-5)","dms(30,15,0)","dms(-30,15,0)","rad(pi)","grad(100)","pol(3,4)","X","Y","rec(5,0)","Y","200*10%","pctadd(200,10)","pctsub(200,10)","pctchange(80,100)","2+3:Ans*4","1E-3","3E2","2³","√(16)"};
        double[] vs={14,20,-4,.125,512,2*Math.PI,14,.5,7d/3,9,-3,-2,.5,.5,1,30,60,45,0,1,0,0,0,0,2,1,Math.E,1000,3,120,120,10,20,.25,5,30.25,-30.25,180,90,5,5,Math.toDegrees(Math.atan2(4,3)),5,0,20,220,180,25,20,.001,300,8,4};
        for(int i=0;i<xs.length;i++){try{eq(e.evaluate(xs[i]),vs[i]);}catch(Throwable ex){throw new AssertionError(xs[i],ex);}}
        e.angle=FormulaEngine.Angle.RAD;eq(e.evaluate("sin(pi/2)"),1);e.angle=FormulaEngine.Angle.GRAD;eq(e.evaluate("sin(100)"),1);e.angle=FormulaEngine.Angle.DEG;
        e.variables.put("A",7d);eq(e.evaluate("A+2"),9);eq(e.evaluate("Ans*2"),18);
        e.format=FormulaEngine.Format.FIX;e.digits=2;ok(e.display(2.5).equals("2.50"));eq(e.evaluate("rnd(1.236)"),1.24);e.format=FormulaEngine.Format.SCI;e.digits=3;ok(e.display(1250).equals("1.25E+03"));e.format=FormulaEngine.Format.ENG;ok(e.display(12345).equals("12.345E3"));e.format=FormulaEngine.Format.FRACTION;ok(e.display(.75).equals("3/4"));e.format=FormulaEngine.Format.MIXED;ok(e.display(2.25).equals("2 1/4"));e.format=FormulaEngine.Format.DMS;ok(e.display(30.25).equals("30° 15′ 0″"));double ran=e.evaluate("ran()");ok(ran>=0&&ran<1);
        for(String s:new String[]{"1/0","sqrt(-1)","tan(90)","5/","(2+3","fact(-1)","ncr(3,4)","root(2,-8)","logbase(1,3)","ran(1)","1::2","1:1/0"})bad(()->e.evaluate(s));eq(e.ans,ran);eq(e.evaluate("mod(17,5)"),2);eq(e.evaluate("pctrate(20,80)"),25);eq(e.evaluate("1+2:Ans*3"),9);ok(e.statementResults.size()==2);eq(e.statementResults.get(0),3);e.format=FormulaEngine.Format.NORM;ok(e.display(.001).contains("E"));e.format=FormulaEngine.Format.NORM2;ok(!e.display(.001).contains("E"));
        List<FormulaStats.Row> sd=FormulaStats.parse("10\n20\n30\n40\n50",false);Map<String,Double> v=FormulaStats.summarize(sd,false);eq(v.get("n"),5);eq(v.get("sumx"),150);eq(v.get("sumx2"),5500);eq(v.get("meanx"),30);eq(v.get("sigmax"),Math.sqrt(200));eq(v.get("sdx"),Math.sqrt(250));
        v=FormulaStats.summarize(FormulaStats.parse("1,2\n5,2",false),false);eq(v.get("n"),4);eq(v.get("meanx"),3);eq(v.get("sdx"),Math.sqrt(16d/3));
        List<FormulaStats.Row> original=FormulaStats.parse("10,1003\n15,1005\n20,1010\n25,1011\n30,1014",true);FormulaStats.Fit f=FormulaStats.fit(original,FormulaStats.Model.LINEAR);eq(f.a,997.4);eq(f.b,.56);eq(f.r,.982607368);eq(f.predict(-5),994.6);eq(f.inverse(1000)[0],4.642857143);eq(FormulaStats.summarize(original,true).get("cov"),35);
        List<FormulaStats.Row> quad=FormulaStats.parse("29,1.6\n50,23.5\n74,38\n103,46.4\n118,48",true);f=FormulaStats.fit(quad,FormulaStats.Model.QUADRATIC);eq(f.a,-35.59856934);eq(f.b,1.495939413);eq(f.c,-.00671629667);eq(f.predict(16),-13.38291067);double[] roots=f.inverse(20);Arrays.sort(roots);eq(roots[0],47.14556728);eq(roots[1],175.5872105);
        for(FormulaStats.Model m:FormulaStats.Model.values()){List<FormulaStats.Row> d=new ArrayList<>();for(int x=1;x<=6;x++){double y;switch(m){case LOG:y=2+3*Math.log(x);break;case EXP:y=2*Math.exp(3*x);break;case POWER:y=2*Math.pow(x,3);break;case INVERSE:y=2+3d/x;break;case QUADRATIC:y=2+3*x+4*x*x;break;default:y=2+3*x;}d.add(new FormulaStats.Row(x,y,1));}FormulaStats.Fit q=FormulaStats.fit(d,m);eq(q.a,2);eq(q.b,3);if(m==FormulaStats.Model.QUADRATIC)eq(q.c,4);eq(q.predict(3),d.get(2).y);double[] inv=q.inverse(d.get(2).y);ok(Arrays.stream(inv).anyMatch(x->Math.abs(x-3)<1e-9));}
        bad(()->FormulaStats.parse("3,0",false));bad(()->FormulaStats.fit(FormulaStats.parse("1,2\n1,3",true),FormulaStats.Model.LINEAR));bad(()->FormulaStats.fit(FormulaStats.parse("-1,2\n2,3",true),FormulaStats.Model.LOG));bad(()->FormulaStats.fit(FormulaStats.parse("1,2\n2,3\n2,4",true),FormulaStats.Model.QUADRATIC));System.out.println("PASS "+count+" Formula Pro assertions");}
}
